<?php

declare(strict_types=1);

namespace Sofy\View;

/**
 * Sofy icon library — Feather-style stroke SVGs that inherit colour from
 * surrounding text via stroke="currentColor". Drop one anywhere a string
 * is expected:
 *
 *   echo Icons::HOME;                          // raw SVG string
 *   echo UI::icon('home', size: 20);           // sized, themed Component
 *   Admin::menu()->add(..., '/x')->icon(Icons::SETTINGS);
 *
 * Every icon is a 24-viewBox SVG with stroke="currentColor" and
 * stroke-width="2", so they pick up the page's --text colour and the
 * active-item --accent automatically. To recolour or resize, wrap in
 * UI::icon() — it rewrites width/height/stroke-width inline.
 *
 * Names map 1:1 with Feather Icons (https://feathericons.com), so any
 * lookup table from that catalog applies.
 */
class Icons
{
