    // ── Lookup helpers ───────────────────────────────────────────────────────

    /**
     * Return an icon's SVG string by name. Accepts kebab-case ("user-plus"),
     * snake_case ("user_plus") or upper-case constant names ("USER_PLUS").
     * Returns empty string when the icon does not exist (so callers can
     * silently degrade rather than crash on a typo).
     */
    public static function get(string $name): string
    {
        $const = strtoupper(str_replace('-', '_', $name));
        $full  = static::class . '::' . $const;
        return defined($full) ? (string) constant($full) : '';
    }

    public static function has(string $name): bool
    {
        return self::get($name) !== '';
    }

    /** @return list<string>  All available icon names in lower-kebab-case, sorted. */
    public static function names(): array
    {
        $r = new \ReflectionClass(static::class);
        $out = [];
        foreach (array_keys($r->getConstants()) as $name) {
            $out[] = strtolower(str_replace('_', '-', $name));
        }
        sort($out);
        return $out;
    }
}
